('prod-dji-rs-4-gimbal', 'dji-rs-4-gimbal', 'DJI RS 4 Gimbal Chống Rung Máy Ảnh', 'TC-DJI-RS4', 'b-dji', 'cat-gimbal', 'Gimbal chống rung chuyên nghiệp, tải trọng 3kg.', 'DJI RS 4 hỗ trợ cân bằng nhanh và quay dọc native.', '{"Tải trọng tối đa":"3.0kg","Thời lượng pin":"12 giờ","Khóa trục":"Tự động thế hệ 2"}', '["DJI RS 4","Tay nắm pin","Đế tháo nhanh","Mini tripod","Hộp chống sốc"]', 160000, 2000000, 'https://images.unsplash.com/photo-1588872657578-7efd1f1555ed?q=80&w=1000&auto=format&fit=crop', '["https://images.unsplash.com/photo-1588872657578-7efd1f1555ed?q=80&w=1000&auto=format&fit=crop"]', 7, 'ACTIVE', 'Thuê DJI RS 4 Gimbal | THUECAM', 'Cho thuê DJI RS 4 tại THUECAM.', 'https://thuecam.vn/thiet-bi/dji-rs-4-gimbal', 'https://images.unsplash.com/photo-1588872657578-7efd1f1555ed?q=80&w=1200&auto=format&fit=crop', true)
insert into public.articles (id, slug, type, title, excerpt, content, featured_image, author_name, reviewer_name, pillar_slug, related_product_ids, status, seo_title, seo_description, canonical_url, og_image, indexable, published_at, updated_at) values
('art-pillar-thue-camera-du-lich', 'thue-camera-du-lich', 'landing', 'Dịch Vụ Cho Thuê Camera Du Lịch Trọn Gói Giá Rẻ', 'Hướng dẫn chọn camera du lịch, thiết bị phù hợp và thủ tục thuê.', '## Thuê camera du lịch tại THUECAM\n\nChọn thiết bị theo hoạt động: action camera cho ngoài trời, pocket camera cho vlog và camera 360 cho góc quay linh hoạt. Kiểm tra lịch trống và phụ kiện trước khi đặt thuê.', 'https://images.unsplash.com/photo-1488646953014-85cb44e25828?q=80&w=1200&auto=format&fit=crop', 'Đội ngũ THUECAM', 'Đội ngũ THUECAM', 'thue-camera-du-lich', '["prod-dji-pocket-4-creator","prod-gopro-hero-13-black","prod-insta360-x4"]', 'PUBLISHED', 'Thuê Camera Du Lịch | THUECAM', 'Tìm camera du lịch, action cam và pocket camera cho chuyến đi.', 'https://thuecam.vn/thue-camera-du-lich', 'https://images.unsplash.com/photo-1488646953014-85cb44e25828?q=80&w=1200&auto=format&fit=crop', true, '2026-09-01T08:00:00Z', '2026-09-20T10:00:00Z'),
('art-dji-pocket-4-la-gi', 'dji-pocket-4-la-gi', 'blog', 'DJI Pocket 4 là gì? Có phù hợp để quay vlog du lịch không?', 'Tổng quan camera pocket và các yếu tố cần cân nhắc khi quay vlog.', 'DJI Pocket 4 là camera cầm tay tích hợp gimbal dành cho nội dung di động. Bài viết giới thiệu các điểm cần cân nhắc khi chọn thiết bị quay vlog.', 'https://images.unsplash.com/photo-1512790182412-b19e6d62bc39?q=80&w=1000&auto=format&fit=crop', 'Đội ngũ THUECAM', 'Đội ngũ THUECAM', 'thue-camera-du-lich', '["prod-dji-pocket-4-creator","prod-dji-pocket-3-creator"]', 'PUBLISHED', 'DJI Pocket 4 Là Gì? | THUECAM', 'Tổng quan DJI Pocket 4 và cách chọn camera quay vlog.', 'https://thuecam.vn/blog/dji-pocket-4-la-gi', 'https://images.unsplash.com/photo-1512790182412-b19e6d62bc39?q=80&w=1200&auto=format&fit=crop', true, '2026-09-05T09:00:00Z', '2026-09-18T14:00:00Z'),
('art-comp-pocket-4-vs-pocket-3', 'dji-pocket-4-vs-pocket-3', 'comparison', 'DJI Pocket 4 vs Pocket 3: Nên thuê máy nào cho chuyến đi?', 'So sánh nhu cầu sử dụng, tính năng và mức giá thuê giữa hai mẫu pocket camera.', 'Khi chọn giữa các thế hệ pocket camera, hãy so sánh tính năng cần dùng, phụ kiện đi kèm và ngân sách thuê. Kiểm tra thông số sản phẩm trước khi quyết định.', 'https://images.unsplash.com/photo-1516035069371-29a1b244cc32?q=80&w=1000&auto=format&fit=crop', 'Đội ngũ THUECAM', null, 'thue-camera-du-lich', '["prod-dji-pocket-4-creator","prod-dji-pocket-3-creator"]', 'PUBLISHED', 'So Sánh DJI Pocket 4 vs Pocket 3 | THUECAM', 'So sánh hai mẫu DJI Pocket để chọn thiết bị phù hợp.', 'https://thuecam.vn/so-sanh/dji-pocket-4-vs-pocket-3', 'https://images.unsplash.com/photo-1516035069371-29a1b244cc32?q=80&w=1200&auto=format&fit=crop', true, '2026-09-08T08:00:00Z', '2026-09-19T10:00:00Z'),
('art-guide-pocket-4-quay-du-lich', 'dji-pocket-4-quay-du-lich', 'guide', 'Hướng dẫn cài đặt DJI Pocket 4 quay du lịch sắc nét từ A-Z', 'Hướng dẫn chuẩn bị camera pocket trước chuyến đi.', 'Trước khi quay, hãy kiểm tra pin, thẻ nhớ, độ phân giải và chế độ chống rung. Chọn tốc độ màn trập phù hợp điều kiện sáng và thử âm thanh trước khi ghi hình.', 'https://images.unsplash.com/photo-1512790182412-b19e6d62bc39?q=80&w=1000&auto=format&fit=crop', 'Đội ngũ THUECAM', null, 'thue-camera-du-lich', '["prod-dji-pocket-4-creator"]', 'PUBLISHED', 'Hướng Dẫn DJI Pocket 4 Quay Du Lịch | THUECAM', 'Hướng dẫn chuẩn bị DJI Pocket 4 cho chuyến du lịch.', 'https://thuecam.vn/huong-dan/dji-pocket-4-quay-du-lich', 'https://images.unsplash.com/photo-1512790182412-b19e6d62bc39?q=80&w=1200&auto=format&fit=crop', true, '2026-09-10T10:00:00Z', '2026-09-20T16:00:00Z')
